INSERT INTO public.participants (id, name, avatar, province, region, organization, generation, bio, interests, powers_have, powers_need, source) VALUES
('11111111-1111-4111-8111-000000000001','ครูนก','👩🏻‍🏫','Chiang Mai','North','โรงเรียนชุมชนบ้านแม่ริม','Gen X','ทำงานกับเยาวชนในพื้นที่สูงมา 12 ปี อยากขยายเครือข่ายสุขภาวะวัยรุ่น',ARRAY['Youth','Mental Health','Community Health'],ARRAY['Community Network','Local Knowledge'],ARRAY['Funding / Resources','Digital Innovation'],'demo'),
('11111111-1111-4111-8111-000000000002','พี่หมูแดง','🧑🏽‍🌾','Khon Kaen','Northeast','วิสาหกิจชุมชนอีสานยั่งยืน','Millennial','ปลูกผักอินทรีย์และทำตลาดสีเขียว อยากเชื่อมนโยบายอาหารปลอดภัย',ARRAY['Environment','Economic Inequality','Policy'],ARRAY['Community Network','Partnership'],ARRAY['Policy Connection','Communication'],'demo'),
('11111111-1111-4111-8111-000000000003','ฟ้า','🧑🏻‍💻','Bangkok Metropolis','Bangkok','Tech for Good TH','Gen Z','นักพัฒนาแอปเพื่อสังคม ชอบทำเครื่องมือให้กลุ่มเปราะบางเข้าถึงบริการ',ARRAY['Digital Innovation','Human Rights','LGBTQ+'],ARRAY['Technology','Creativity'],ARRAY['Local Knowledge','Community Network'],'demo'),
('11111111-1111-4111-8111-000000000004','หมออั๋น','🧑🏻‍⚕️','Songkhla','South','รพ.สต. เขตสงขลา','Millennial','หมอครอบครัว สนใจสุขภาพจิตวัยทำงานและระบบส่งต่อในชุมชน',ARRAY['Mental Health','Community Health','Silver Age'],ARRAY['Knowledge','Partnership'],ARRAY['Communication','Technology'],'demo'),
('11111111-1111-4111-8111-000000000005','พี่แดง','👩🏽','Ubon Ratchathani','Northeast','กลุ่มผู้หญิงลุ่มน้ำมูล','Gen X','ขับเคลื่อนเรื่องความเท่าเทียมทางเพศและยุติความรุนแรงในครอบครัว',ARRAY['Gender Equality','Gender-Based Violence','Human Rights'],ARRAY['Community Network','Communication'],ARRAY['Policy Connection','Funding / Resources'],'demo'),
('11111111-1111-4111-8111-000000000006','ต้นกล้า','🧑🏼‍🎨','Nakhon Ratchasima','Northeast','สตูดิโอสื่อสารสร้างสรรค์','Gen Z','ทำสื่อรณรงค์ อินโฟกราฟิก และวิดีโอสั้นให้ภาคประชาสังคม',ARRAY['Youth','Digital Innovation','Sexual Health'],ARRAY['Creativity','Communication'],ARRAY['Knowledge','Funding / Resources'],'demo'),
('11111111-1111-4111-8111-000000000007','ป้าสมศรี','👵🏻','Lampang','North','ชมรมผู้สูงอายุเทศบาลลำปาง','Boomer','ดูแลกิจกรรมผู้สูงวัยและโรงเรียนผู้สูงอายุในเขตเทศบาล',ARRAY['Silver Age','Community Health'],ARRAY['Local Knowledge','Community Network'],ARRAY['Technology','Ideas'],'demo'),
('11111111-1111-4111-8111-000000000008','กานต์','🧑🏻‍💼','Chon Buri','Central','มูลนิธิพัฒนาแรงงานภาคตะวันออก','Millennial','ทำงานสิทธิแรงงานข้ามชาติและการเข้าถึงบริการสุขภาพ',ARRAY['Human Rights','Economic Inequality','Community Health'],ARRAY['Policy Connection','Knowledge'],ARRAY['Community Network','Creativity'],'demo'),
('11111111-1111-4111-8111-000000000009','มะปราง','👩🏻‍🔬','Phuket','South','เครือข่ายเยาวชนอันดามัน','Gen Z','ทำงานสุขภาวะทางเพศและความหลากหลายในกลุ่มเยาวชนชายฝั่ง',ARRAY['LGBTQ+','Sexual Health','Youth'],ARRAY['Ideas','Communication'],ARRAY['Knowledge','Policy Connection'],'demo'),
('11111111-1111-4111-8111-00000000000a','พี่โจ','🧑🏾','Nakhon Si Thammarat','South','กองทุนสุขภาพตำบล','Gen X','ดูแลกองทุนสุขภาพตำบล อยากหาโมเดลใหม่ให้ชุมชนจัดการตัวเอง',ARRAY['Community Health','Policy','Environment'],ARRAY['Funding / Resources','Policy Connection'],ARRAY['Ideas','Digital Innovation'],'demo');
INSERT INTO public.ideas (id, title, description, owner_id, region, issues, resources_have, resources_need) VALUES
('22222222-2222-4222-8222-000000000001','ห้องเรียนสุขภาพจิตวัยรุ่นบนดอย','จัดกระบวนการดูแลใจในโรงเรียนพื้นที่สูง 5 แห่ง พร้อมพี่เลี้ยงชุมชน','11111111-1111-4111-8111-000000000001','North',ARRAY['Youth','Mental Health'],ARRAY['Community Network','Local Knowledge'],ARRAY['Funding / Resources','Knowledge']),
('22222222-2222-4222-8222-000000000002','ตลาดเขียวอีสานเชื่อมนโยบายอาหาร','ยกระดับตลาดผักอินทรีย์ให้เข้าสู่ระบบจัดซื้อโรงพยาบาลและโรงเรียน','11111111-1111-4111-8111-000000000002','Northeast',ARRAY['Environment','Policy'],ARRAY['Community Network','Partnership'],ARRAY['Policy Connection','Communication']),
('22222222-2222-4222-8222-000000000003','แอปนัดหมายบริการสุขภาพเพื่อนกลุ่มเปราะบาง','เครื่องมือจองคิวและส่งต่อบริการแบบไม่เปิดเผยตัวตน','11111111-1111-4111-8111-000000000003','Bangkok',ARRAY['Digital Innovation','LGBTQ+'],ARRAY['Technology','Creativity'],ARRAY['Local Knowledge','Community Network']),
('22222222-2222-4222-8222-000000000004','เพื่อนรับฟังในชุมชน','อบรมอาสาสมัครรับฟังเบื้องต้น เชื่อมระบบส่งต่อกับ รพ.สต.','11111111-1111-4111-8111-000000000004','South',ARRAY['Mental Health','Community Health'],ARRAY['Knowledge','Partnership'],ARRAY['Communication','Technology']),
('22222222-2222-4222-8222-000000000005','โรงเรียนผู้สูงอายุออนไลน์','ทำคลิปสั้นและคู่มือให้ชมรมผู้สูงอายุใช้เองได้ทั่วประเทศ','11111111-1111-4111-8111-000000000007','Nationwide',ARRAY['Silver Age','Digital Innovation'],ARRAY['Local Knowledge','Community Network'],ARRAY['Technology','Creativity']);